const f = $input.first().json;
const bins = $input.first().binary || {};
const out = { json: {
  cfg: {
    shop: 'REPLACE_STORE.myshopify.com', store_name: 'Your Store', return_window_days: 7, damage_window_days: 3,
    non_returnable_tags: ['final-sale', 'innerwear', 'personal-care', 'no-return'], manual_review_value: 5000,
    abuse_returns_90d: 3, credit_bonus_pct: 10, return_fee: 99, ai_min_confidence: 0.7,
    choice_webhook: 'https://REPLACE-N8N-DOMAIN/webhook/return-choice',
    warehouse: { name: 'Your Store Returns', address: 'Warehouse address line', city: 'Your City', state: 'Your State', pincode: '000000', phone: '9XXXXXXXXX' },
    policy_text: 'Returns accepted within 7 days of delivery for unused items with tags attached. Damaged/defective or wrong items must be reported within 3 days with photos. Final-sale, innerwear and personal-care items are non-returnable. Size exchanges are free. Change-of-mind returns get store credit or an exchange; refunds carry a ₹99 reverse-pickup fee.'
  },
  order_no: String(f['Order Number'] || '').replace(/[^0-9A-Za-z-]/g, ''),
  contact: String(f['Email or Phone used for the order'] || '').trim().toLowerCase(),
  items_text: f['Item(s) to return'], reason: f['Reason'], description: f['Describe the issue'],
  preferred: f['Preferred resolution'], exchange_variant: f['Exchange size/variant wanted (if exchange)'] || '',
  photo_count: Object.keys(bins).length, submitted_at: new Date().toISOString(),
  return_id: `RET-${$now.toFormat('yyLLdd')}-${Math.random().toString(36).slice(2, 7).toUpperCase()}`
}, binary: bins };
return [out];

const req = $('Set Return Policy & Config').first().json, cfg = req.cfg;
const o = $('Look Up Order in Shopify').first().json.body?.data?.orders?.edges?.[0]?.node;
const log = $input.all().map(i => i.json).filter(r => r.return_id);
const fail = [], manual = [];
let deliveredAt = null, days = null, items = [], value = 0, phone = '', email = '';
if (!o) fail.push(`We couldn't find order #${req.order_no}`);
else {
  email = String(o.email || o.customer?.email || '').toLowerCase();
  phone = String(o.phone || o.shippingAddress?.phone || o.customer?.phone || '').replace(/\D/g, '');
  const c = req.contact.replace(/\s/g, '');
  const contactOk = (c.includes('@') && c === email) || (c.replace(/\D/g, '').slice(-10) && phone.endsWith(c.replace(/\D/g, '').slice(-10)));
  if (!contactOk) fail.push('The email/phone does not match this order');
  const f = (o.fulfillments || []).sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)))[0];
  deliveredAt = f?.deliveredAt || (f ? DateTime.fromISO(f.createdAt).plus({ days: 4 }).toISO() : null);   // fallback estimate
  if (!f) fail.push('This order has not been delivered yet');
  else days = Math.floor($now.diff(DateTime.fromISO(deliveredAt), 'days').days);
  const isDamage = /damaged|wrong item/i.test(req.reason);
  const window = isDamage ? cfg.damage_window_days : cfg.return_window_days;
  if (days !== null && days > window) fail.push(`The return window (${window} days from delivery) has passed. It was delivered ${days} days ago.`);
  const lines = (o.lineItems?.edges || []).map(e => e.node);
  const toks = s => String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 1);
  const want = toks(req.items_text);
  items = lines.filter(l => { const t = toks(`${l.title} ${l.variant?.title} ${l.sku}`); return want.filter(w => t.includes(w)).length >= Math.min(2, want.length); });
  if (!items.length && lines.length === 1) items = lines;
  if (!items.length) fail.push(`We couldn't match "${req.items_text}" to the items in this order`);
  const blocked = items.filter(l => (l.variant?.product?.tags || []).some(t => cfg.non_returnable_tags.includes(String(t).toLowerCase())));
  if (blocked.length) fail.push(`${blocked.map(b => b.title).join(', ')} is non-returnable as per policy`);
  value = items.reduce((a, l) => a + Number(l.discountedUnitPriceSet?.shopMoney?.amount || 0) * l.quantity, 0);
  if (log.some(r => r.order_no === req.order_no && items.some(i => String(r.items).includes(i.title)) && !/rejected|cancel/i.test(r.status))) fail.push('A return for this item is already in progress');
  const recent = log.filter(r => (r.email === email || (phone && String(r.phone).endsWith(phone.slice(-10)))) && new Date(r.created_at) > new Date(Date.now() - 90 * 864e5));
  if (recent.length >= cfg.abuse_returns_90d) manual.push(`${recent.length} returns in 90 days`);
  if (value > cfg.manual_review_value) manual.push(`high value ₹${value}`);
  if (req.photo_count === 0) manual.push('no photos');
}
return [{ json: { ...req, eligible: !fail.length, fail_reasons: fail, manual_flags: manual, order_gid: o?.id || '', order_name: o?.name || `#${req.order_no}`,
  customer_gid: o?.customer?.id || '', customer_name: o?.shippingAddress?.name || '', email, phone, ship_to: o?.shippingAddress || {},
  ship_to_json: JSON.stringify(o?.shippingAddress || {}), delivered_at: deliveredAt, days_since_delivery: days, items: items.map(l => ({ title: l.title, variant: l.variant?.title, sku: l.sku, qty: l.quantity,
    price: Number(l.discountedUnitPriceSet?.shopMoney?.amount || 0), product_type: l.variant?.product?.productType })), item_value: Math.round(value * 100) / 100 },
  binary: $('Set Return Policy & Config').first().binary || {} }];

const r = $input.first().json;
const bins = $input.first().binary || {};
const imgs = [];
let i = 0;
for (const k of Object.keys(bins).slice(0, 4)) {
  const buf = await this.helpers.getBinaryDataBuffer(0, k).catch(() => null);
  if (buf) imgs.push({ type: 'image_url', image_url: { url: `data:${bins[k].mimeType || 'image/jpeg'};base64,${buf.toString('base64')}`, detail: 'high' } });
  i++;
}
return [{ json: { ...r, vision_body: { model: 'gpt-4o', temperature: 0, response_format: { type: 'json_object' }, messages: [
  { role: 'system', content: `You are a returns inspector for an Indian e-commerce store. Compare the customer's photos with their claim, the ordered item and the store policy.
Policy: ${r.cfg.policy_text}
Return ONLY JSON: {"item_matches_order": boolean, "damage_visible": boolean, "matches_claim": boolean, "damage_type": string|null, "severity": "none"|"minor"|"major",
"signs_of_use": boolean, "tags_attached": boolean|null, "fraud_flags": [string] (e.g. stock/internet photo, different product, edited image, damage looks caused after delivery),
"confidence": number (0-1), "summary": string (max 35 words, neutral)}. Judge only what is visible; if the photos are unclear, lower the confidence.` },
  { role: 'user', content: [{ type: 'text', text: `Order items: ${JSON.stringify(r.items)}\nReason: ${r.reason}\nCustomer says: ${r.description}` }, ...imgs] } ] } } }];

const r = $('Prepare Vision Request').first().json, cfg = r.cfg;
let ai = {};
try { ai = JSON.parse($input.first().json.choices?.[0]?.message?.content || '{}'); } catch (e) { ai = { confidence: 0, fraud_flags: ['AI check failed'] }; }
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const token = hex(24);
const defect = /damaged|wrong item|quality/i.test(r.reason);
const flags = [...r.manual_flags];
if ((ai.confidence ?? 0) < cfg.ai_min_confidence) flags.push(`low AI confidence (${ai.confidence ?? 0})`);
if ((ai.fraud_flags || []).length) flags.push(...ai.fraud_flags.map(f => 'AI: ' + f));
if (ai.item_matches_order === false) flags.push('photo item does not match the order');
if (defect && ai.matches_claim === false) flags.push('damage claim not visible in photos');
let decision = flags.length ? 'manual_review' : 'offer';
let decline = '';
if (!defect && ai.signs_of_use === true && (ai.confidence ?? 0) >= 0.8) { decision = 'reject'; decline = 'The photos show signs of use, and our policy only accepts unused items with tags for this reason.'; }
const value = r.item_value, credit = Math.round(value * (1 + cfg.credit_bonus_pct / 100));
const refund = defect ? value : Math.max(0, value - cfg.return_fee);
const offers = [];
if (/size|fit/i.test(r.reason) || /exchange/i.test(r.preferred)) offers.push({ key: 'exchange', label: `🔄 Exchange${r.exchange_variant ? ' for ' + r.exchange_variant : ''} (free pickup)` });
offers.push({ key: 'credit', label: `🎁 Store credit ₹${credit} (+${cfg.credit_bonus_pct}% bonus, instant)` });
if (!offers.find(o => o.key === 'exchange')) offers.push({ key: 'exchange', label: '🔄 Exchange for another size/colour' });
if (defect || !/changed my mind/i.test(r.reason)) offers.push({ key: 'refund', label: `💸 Refund ₹${refund}${defect ? '' : ` (after ₹${cfg.return_fee} pickup fee)`}` });
const link = k => `${cfg.choice_webhook}?id=${r.return_id}&t=${token}&c=${k}`;
return [{ json: { ...r, ai_check: ai, ai_summary: ai.summary || '', ai_confidence: ai.confidence ?? 0, decision, decline_reason: decline,
  review_flags: flags, defect, credit_amount: credit, refund_amount: refund, token,
  offers: offers.map(o => ({ ...o, url: link(o.key) })), agent_approve_url: link('agent_approve'), agent_reject_url: link('agent_reject') } }];

const q = $('On Choice or Review Link Click').first().json.query || {};
const r = $input.first()?.json || {};
const c = String(q.c || '');
let reason = '';
if (!r.return_id) reason = 'Return not found';
else if (!r.token || r.token === 'used' || r.token !== q.t) reason = 'This link was already used or is invalid';
else if (c.startsWith('agent_') && r.status !== 'manual_review') reason = 'Already reviewed';
else if (!c.startsWith('agent_') && r.status !== 'offer_sent') reason = `Return is ${r.status}`;
else if (!['exchange', 'credit', 'refund', 'agent_approve', 'agent_reject'].includes(c)) reason = 'Unknown option';
return [{ json: { ...r, choice: c, valid: !reason, reason } }];

const r = $('Validate Choice').first().json;
const WH = { name: 'Your Store Returns', address: 'Warehouse address line', city: 'Your City', state: 'Your State', pincode: '000000', phone: '9XXXXXXXXX' };
let ship = {};
try { ship = JSON.parse(r.ship_to_json || '{}'); } catch (e) {}
return [{ json: { token: $input.first().json.token, r, body: {
  order_id: r.return_id, order_date: $now.toFormat('yyyy-LL-dd'), channel_id: '',
  pickup_customer_name: r.customer_name || 'Customer', pickup_address: ship.address1 || r.pickup_address || '', pickup_address_2: ship.address2 || '',
  pickup_city: ship.city || r.pickup_city || '', pickup_state: ship.province || r.pickup_state || '', pickup_country: 'India',
  pickup_pincode: ship.zip || r.pickup_pincode || '', pickup_email: r.email, pickup_phone: String(r.phone).slice(-10),
  shipping_customer_name: WH.name, shipping_address: WH.address, shipping_city: WH.city, shipping_country: 'India',
  shipping_pincode: WH.pincode, shipping_state: WH.state, shipping_phone: WH.phone,
  order_items: String(r.items || 'Return item').split('; ').map((t, i) => ({ name: t, sku: `RET-${i + 1}`, units: 1, selling_price: Math.round(Number(r.item_value) / Math.max(1, String(r.items).split('; ').length)) })),
  payment_method: 'Prepaid', sub_total: Number(r.item_value) || 0, length: 30, breadth: 25, height: 8, weight: 0.8 } } }];

const r = $('Validate Choice').first().json;
const p = $('Create Reverse Pickup in Shiprocket').first().json;
const pb = p.body || {};
const pickupOk = p.statusCode >= 200 && p.statusCode < 300 && (pb.order_id || pb.shipment_id);
let giftCode = '', giftErr = '';
if ($('Issue Store Credit Gift Card').isExecuted) {
  const g = $('Issue Store Credit Gift Card').first().json.body?.data?.giftCardCreate;
  giftCode = g?.giftCardCode || ''; giftErr = (g?.userErrors || []).map(e => e.message).join('; ') || (g ? '' : 'gift card API error');
}
const label = { exchange: 'Exchange', credit: 'Store credit', refund: 'Refund' }[r.choice];
const msg = `✅ ${label} confirmed for ${r.return_id}.\n` + (pickupOk ? `🚚 Free pickup booked${pb.awb_code ? ` (AWB ${pb.awb_code})` : ''}. Please keep the item packed with its tags.\n` : `🚚 Our team will confirm your pickup slot shortly.\n`) +
  (r.choice === 'credit' ? (giftCode ? `🎁 Your store credit code: *${giftCode}* (₹${r.credit_amount}). Use it at checkout any time.` : '🎁 Your store credit will be emailed shortly.') :
   r.choice === 'exchange' ? '🔄 Your replacement ships as soon as the pickup is scanned.' : `💸 Your refund of ₹${r.refund_amount} will be processed within 2–3 days of the item reaching us.`);
return [{ json: { ...r, label, pickup_ok: !!pickupOk, pickup_ref: pb.shipment_id || pb.order_id || '', awb: pb.awb_code || '', pickup_error: pickupOk ? '' : JSON.stringify(pb).slice(0, 200),
  gift_code_masked: giftCode ? giftCode.slice(0, 4) + '••••' + giftCode.slice(-4) : '', gift_error: giftErr, customer_msg: msg,
  needs_ops: !pickupOk || !!giftErr || r.choice !== 'credit' } }];

